/* From Uiverse.io by albertofanini-prog - Tags: button */
.__UIV_SCOPE__ .pulsa {
  animation: pulsa 1.4s infinite;
  min-width: 200px;
  width: fit-content;
  border-radius: 9999px;
  /* overflow: hidden; */
}

.__UIV_SCOPE__ .cta {
  width: 100%;
  height: 100%;
  border: none;
  outline: none;
  background-color: none;
  border-radius: 9999px;
  padding: 8px 16px;
  color: white;
  font-size: 15px;
  background: linear-gradient(109.6deg, #090979 11.2%, #9006A1 53.7%, #090979 100.2%);
  letter-spacing: 0.08em;
  font-weight: 800;
  position: relative;
}

.__UIV_SCOPE__ .cta:active {
  animation: pulsa-active .4s infinite;
}

.__UIV_SCOPE__ .star {
  width: 2px;
  height: 2px;
  background-color: white;
  border-radius: 50%;
  position: absolute;
  animation: pulsa-stella 1.8s infinite;
  transition: all .8s ease-in-out;
}

.__UIV_SCOPE__ .star.a {
  top: 8px;
  left: 6px;
}

.__UIV_SCOPE__ .star.b {
  top: 2px;
  left: 16px;
}

.__UIV_SCOPE__ .star.c {
  top: 18px;
  left: 8px;
}

.__UIV_SCOPE__ .star.d {
  top: 14px;
  left: 20px;
}

.__UIV_SCOPE__ .star.e {
  top: 30px;
  left: 8px;
}

.__UIV_SCOPE__ .star.f {
  top: 24px;
  left: 24px;
}

.__UIV_SCOPE__ .star.g {
  top: 10px;
  left: 32px;
}

.__UIV_SCOPE__ .pulsa:hover .star.a {
  transform: translate3d(0px, 8px, 0);
}

.__UIV_SCOPE__ .pulsa:hover .star.b {
  transform: translate3d(-4px, 6px, 0);
}

.__UIV_SCOPE__ .pulsa:hover .star.c {
  transform: translate3d(14px, -8px, 0);
}

.__UIV_SCOPE__ .pulsa:hover .star.d {
  transform: translate3d(16px, -2px, 0);
}

.__UIV_SCOPE__ .pulsa:hover .star.e {
  transform: translate3d(58px, -20px, 0);
}

.__UIV_SCOPE__ .pulsa:hover .star.f {
  transform: translate3d(34px, 2px, 0);
}

.__UIV_SCOPE__ .pulsa:hover .star.g {
  transform: translate3d(10px, 16px, 0);
}

.__UIV_SCOPE__ .rocket {
  position: absolute;
  top: 8px;
  right: 16px;
  z-index: -1;
  transform: rotate(180deg);
  transition: all .3s ease-in-out;
}

.__UIV_SCOPE__ .pulsa:hover .rocket {
  z-index: auto;
  animation: muovi-razzo 1.8s linear;
  transform: rotate(0deg);
}

@keyframes pulsa {
  0% {
    box-shadow: 0 0 0 0 #9006A1;
  }

  100% {
    box-shadow: 0 0 0 8px #fbb32f01;
  }
}

@keyframes pulsa-stella {
  0% {
    box-shadow: 0 0 0 0 #ffffff;
  }

  100% {
    box-shadow: 0 0 0 4px #fbb32f01;
  }
}

@keyframes muovi-razzo {
  from {
    transform: rotate(180deg);
  }

  25% {
    transform: translate3d(40px, 32px, 0);
  }

  50% {
    transform: translate3d(32px, -60px, 0);
  }

  75% {
    transform: translate3d(0px, -60px, 0) rotate(0);
  }

  to {
    transform: rotate(0deg);
  }
}

@keyframes pulsa-active {
  0% {
    box-shadow: 0 0 0 0 #9006A1;
  }

  100% {
    box-shadow: 0 0 0 16px #fbb32f01;
  }
}
